const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (crear_lote_pendiente) -- Python es la unica autoridad.
// Este nodo NUNCA decide nada de negocio: solo empaqueta lo que ya vino
// del request HTTP (body/query), mas rutas DEV FIJAS del lado servidor
// (el navegador nunca elige un path de archivo -- ver Sticky Note de
// seguridad de este workflow). FASE 10D: base_dir_dev apunta al workdir
// REAL (Drive solo lectura), no al fixture de FASE 9.
const payload = { fecha_inicio: t.body.fecha_inicio, fecha_fin: t.body.fecha_fin, usuario_auditor: t.body.usuario_auditor || null, caja: t.body.caja || null, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_crear_lote_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_crear_lote_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());
const rp = $('RESOLVER procesar_entrada (MACROS y cierres)').first().json;

// Payload para v3.dev_api (procesar_lote) -- Python es la unica autoridad.
// FASE 11A.3: requiere_ingesta_drive=true (modo oficial de este despliegue) -- si EJECUTAR - 01 INGESTA (Drive real) no
// entrego drive_file_id para algun cierre ENCONTRADO (o fallo tecnicamente y t.data.cierres nunca llego),
// v3.dev_api.procesar_lote() rechaza el lote ENTERO (IngestaDriveRequeridaError, estado_lote=ERROR) en vez de caer al
// listado local (os.listdir).
// HOTFIX 2026-09-19: el cierre y MACROS ya NO vienen de copias estaticas locales: se descargaron de Drive en ESTA corrida
// a procesar_entrada/<lote_id>/ (cierres por drive_file_id exacto; MACROS oficial vigente por nombre exacto en su carpeta).
// Plantilla y markers siguen viniendo de sus copias de origen (sin cambios).
// v3.precheck_maestro (Python) sigue decidiendo MAESTRO_APTO/BLOQUEADO (cobertura por fecha de cierre Y de depositos)
// antes de invocar el motor; este nodo no reinterpreta esa decision.
// FIX (bug real, primer intento oficial 10/09): el INTERPRETAR del subworkflow 01 INGESTA envuelve su salida bajo .data
// -> se lee t.data.cierres.
const payload = { lote_id: $('INTERPRETAR resultado crear_lote_pendiente').first().json.data.lote_id, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir', origen_cierres_dir: rp.dir_cierres, ruta_maestro_origen: rp.dir_entrada + '/' + (($('CLASIFICAR - MACROS y cierres de procesar').all().map(function(i){ return i.json; }).find(function(j){ return j && j.tipo === 'macros'; }) || {}).name), ruta_plantilla_origen: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/plantilla_origen/Plantilla SAP maestra.xlsx', markers_origen_dir: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/markers_origen', ingesta_precomputada: (t && t.data && t.data.cierres) || null, requiere_ingesta_drive: true };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_procesar_lote_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_procesar_lote_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (estado) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.query.lote_id, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_estado_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_estado_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (datos) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.query.lote_id, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_datos_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_datos_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (revisar) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.body.lote_id, fecha: t.body.fecha, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_revisar_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_revisar_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (corregir) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
const payload = { lote_id: t.body.lote_id, fecha: t.body.fecha, correccion: t.body.correccion, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir' };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_corregir_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_corregir_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (publicar) -- Python es la unica autoridad.
// FASE 10D: base_dir_dev apunta al workdir REAL (mismo que procesar_lote).
// HOTFIX 2026-09-19: modo_oficial=true -- el paso local solo PREPARA los archivos que 06B sube a Drive (un marcador local
// residual no corta el flujo ni cuenta como publicacion). El estado PUBLICADO solo lo fija la consolidacion posterior,
// con la confirmacion real de 06B/Drive.
const payload = { lote_id: t.body.lote_id, fechas: t.body.fechas, usuario_auditor: t.body.usuario_auditor || null, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir', modo_oficial: true };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_publicar_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_publicar_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const data = $json.data || {};
const publicados = data.publicados || [];
const elegibles = publicados.filter(function(c){ return c && c.ruta_sap_publicado && c.ruta_resultado_publicado && c.ruta_marker && c.sha256; });
return [{ json: { elegibles: elegibles, hay_elegibles: elegibles.length > 0 } }];

const original = $('INTERPRETAR resultado publicar').first().json.data || {};
const drive = $input.all().map(function(it){ return it.json; });
return [{ json: Object.assign({}, original, { publicados_drive_oficial: drive }) }];

// FASE CAJA-AMERICA: /procesar debe pedirle a "01 INGESTA" el folder_entrada
// de la CAJA del LOTE (identidad ya persistida por crear_lote_pendiente,
// nunca del request) -- antes este nodo no existia y "EJECUTAR - 01 INGESTA
// (Drive real)" tenia el folder de 00_ENTRADA_CIERRES de TIQUIPAYA fijo,
// asi que un lote de AMERICA leia igual los cierres de TIQUIPAYA. Copia de
// referencia EXACTA del resolverDestino('entrada') del nodo "RESOLVER -
// Destinos Drive por caja" (06B PUBLICACION OFICIAL / PREFLIGHT OFICIAL) y
// de config_drive_oficial.resolver_destinos_drive() en el backend Python --
// misma identidad; mantener las 3 copias sincronizadas.
const caja = ((($('INTERPRETAR resultado crear_lote_pendiente').first().json.data || {}).caja) || 'tiquipaya').toString().trim().toLowerCase();

if (caja !== 'tiquipaya' && caja !== 'america') {
  throw new Error('CAJA_DESCONOCIDA: "' + caja + '". Cajas validas: america, tiquipaya.');
}

// Default TIQUIPAYA: EXACTAMENTE el folder ID historico de 00_ENTRADA_CIERRES
// (idem config_drive_oficial._TIQ_DEFAULTS['entrada']). AMERICA no tiene
// default a proposito -- sin DRIVE_ENTRADA_AME configurada, falla cerrado,
// nunca hereda el folder de TIQUIPAYA.
const DEFAULT_ENTRADA_TIQ = '1ntneoE3MI-25FyPXUymXEvIJmnaZWyJ1';
const envVar = 'DRIVE_ENTRADA_' + (caja === 'america' ? 'AME' : 'TIQ');
const valor = $env[envVar];
const folderEntrada = valor || (caja === 'tiquipaya' ? DEFAULT_ENTRADA_TIQ : null);
if (!folderEntrada) {
  throw new Error('DRIVE_AME_PENDIENTE: falta configurar ' + envVar + ' (carpeta "entrada" de CAJA AMERICA todavia no existe en Drive).');
}

return [{ json: { caja: caja, folder_entrada: folderEntrada } }];

// FASE 11A.2: el backend (no el frontend) expone el modo real de
// publicacion. 'official' porque, en este despliegue, la rama /publicar
// YA invoca TIQ V3 06B PUBLICACION OFICIAL DRIVE (ver EJECUTAR - 06B...
// en la rama /publicar de este mismo workflow). Si en el futuro /publicar
// se desconecta de 06B, este valor debe cambiar a 'dev' en el mismo lugar
// -- nunca en el frontend. Se agrega SIEMPRE, incluso si Python devolvio
// un ERROR (p. ej. sin lote_id todavia), para que el frontend pueda leer
// el modo apenas carga la pagina, antes de procesar ningun cierre.
const original = $json.data || {};
return [{ json: Object.assign({}, original, { publication_mode: 'official' }) }];

const t = $input.first().json;
const q = t.query || {};

// Harness minimo de solo lectura (FASE 11A.2): reenvia los campos tal
// cual llegaron por query string al subworkflow de preflight -- CERO
// logica de negocio aqui. En produccion estos mismos campos vendrian del
// lote ya procesado (fecha/archivo_esperado/sha256/drive_file_id desde
// ingesta+motor; ruta_sap_publicado/ruta_resultado_publicado son solo
// los NOMBRES oficiales deterministas, no requieren que el cierre ya se
// haya publicado localmente).
return [{
  json: {
    fecha: q.fecha || null,
    archivo_esperado: q.archivo_esperado || null,
    sha256: q.sha256 || null,
    drive_file_id: q.drive_file_id || null,
    ruta_sap_publicado: q.ruta_sap_publicado || null,
    ruta_resultado_publicado: q.ruta_resultado_publicado || null,
  },
}];

const t = $input.first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.dev_api (generar_global) -- Python es la unica autoridad.
// FASE 12C: el navegador SOLO envia anio/mes; base_dir_dev/ruta_plantilla_origen
// son rutas fijas del lado servidor (mismo criterio que /procesar). Cero
// logica contable aqui: este nodo no valida ni decide nada de negocio.
const payload = { anio: t.body.anio, mes: t.body.mes, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir', ruta_plantilla_origen: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/plantilla_origen/Plantilla SAP maestra.xlsx', caja: t.body.caja || 'tiquipaya' };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_global_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_global_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const t = $('WEBHOOK control1').first().json;
const body = t.body || {};
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());
const baseDirDev = '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir';

// CONTROL 1 institucional (un solo boton, no depende del selector de caja):
// PRELIMINAR (por defecto) nunca toca historico ni GLOBAL. CIERRE solo viaja
// si el frontend envia confirmacion_cierre=true explicito (tras confirmacion
// humana) -- aqui NUNCA se infiere el cierre. `caja` NUNCA se lee del body:
// CONTROL 1 institucional no tiene (ni necesita) fallback a 'tiquipaya'.
const confirmacionCierre = body.confirmacion_cierre === true;
const correccionesTiq = Array.isArray(body.correcciones_tiq) ? body.correcciones_tiq : [];
const correccionesAme = Array.isArray(body.correcciones_ame) ? body.correcciones_ame : [];
const hayCorrecciones = confirmacionCierre && (correccionesTiq.length > 0 || correccionesAme.length > 0);

const payload = { anio: body.anio, mes: body.mes, base_dir_dev: baseDirDev, dry_run: body.dry_run || false, confirmacion_cierre: confirmacionCierre };
const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_control1_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_control1_output_' + executionId + '.json';

let comandoCorregir = '';
if (hayCorrecciones) {
  // CIERRE con correcciones autorizadas por el auditor: aplica AMBOS GLOBAL
  // (staging+rollback cross-archivo, ver
  // v3/control1_institucional.aplicar_correcciones_institucional) ANTES de
  // ejecutar_control1_institucional, para que el historico se actualice ya
  // sobre el GLOBAL corregido.
  const payloadCorregir = { anio: body.anio, mes: body.mes, base_dir_dev: baseDirDev, correcciones_tiq: correccionesTiq, correcciones_ame: correccionesAme };
  const rutaCorregirInput = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_corregir_control1_input_' + executionId + '.json';
  const rutaCorregirOutput = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_corregir_control1_output_' + executionId + '.json';
  const corregirB64 = Buffer.from(JSON.stringify(payloadCorregir), 'utf8').toString('base64');
  comandoCorregir = 'printf \'%s\' \'' + corregirB64 + '\' | base64 -d > "' + rutaCorregirInput + '" && ' +
    '/workspaces/.venv-caja/bin/python3 -m v3.dev_api --accion corregir_control1_institucional --input "' + rutaCorregirInput + '" --output "' + rutaCorregirOutput + '" && ' +
    'grep -q \'"resultado": "OK"\' "' + rutaCorregirOutput + '" && ';
}
const comandoEjecutar = 'cd /workspaces/caja-tiquipaya-v2 && ' + comandoCorregir +
  '/workspaces/.venv-caja/bin/python3 -m v3.dev_api --accion ejecutar_control1_institucional --input "' + rutaInputTmp + '" --output "' + rutaOutputTmp + '" ; true';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
    comando_ejecutar: comandoEjecutar,
  },
}];

const t = $('WEBHOOK control3').first().json;
const body = t.body || {};
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// CONTROL 3 institucional (un solo boton, no depende del selector de caja):
// PRELIMINAR (por defecto) nunca toca ningun historico. CIERRE (sella el
// periodo: actualiza HISTORICO_CXC_CXP.csv + su libro de periodos) solo
// viaja si el frontend envia confirmacion_cierre=true explicito (tras
// confirmacion humana) -- aqui NUNCA se infiere el cierre. `caja` NUNCA se
// lee del body: CONTROL 3 institucional no tiene (ni necesita) fallback a
// 'tiquipaya'. CONTROL 3 nunca modifica ningun GLOBAL.
const payload = { anio: body.anio, mes: body.mes, base_dir_dev: '/home/codespace/.n8n-files/tiq_v3_real_readonly_dev/dev_workdir', dry_run: body.dry_run || false, confirmacion_cierre: body.confirmacion_cierre === true };

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_control3_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_dev_api_control3_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

const modo = (($('WEBHOOK global').item.json.body) || {}).modo || 'dev';
const r = $json.data;
const debePublicar = modo === 'official' && r.estado === 'VALIDADO_PENDIENTE_PUBLICACION';
return [{ json: { debe_publicar: debePublicar, ruta_sap: r.ruta_global_generado, ruta_resultado: r.ruta_resultado_json } }];

const d = $('DECIDIR - Publicar GLOBAL oficial').item.json;
const carpetaId = $json.carpeta_id;
return [
  { json: { carpeta_id: carpetaId, nombre_archivo: d.ruta_sap.split('/').pop(), ruta_local_origen: d.ruta_sap, modo_si_existe: 'actualizar' } },
  { json: { carpeta_id: carpetaId, nombre_archivo: d.ruta_resultado.split('/').pop(), ruta_local_origen: d.ruta_resultado, modo_si_existe: 'actualizar' } },
];

const base = $('INTERPRETAR resultado global').item.json.data;
const subidas = $input.all().map(function(i){ return i.json; }).filter(function(j){ return j && Object.keys(j).length; });
return [{ json: { data: Object.assign({}, base, { publicacion_oficial: { publicado: true, archivos: subidas } }) } }];

const t = $json;
const modo = (t.body || {}).modo || 'dev';
return [{ json: { debe_descargar: modo === 'official' } }];

// FASE 12F -- CONTROL 1 institucional: ya no hay UN GLOBAL por caja ni una
// REVISION_ASIGNACIONES por-caja (ver clasificar.js). El resultado que llega
// aqui es el de v3.control1_institucional.ejecutar_control1_institucional
// (mezclado con {resultado, dir_entrada, modo} por v3/dev_api.py):
//   estado, periodo, sha_par, archivo_global_tiq, archivo_global_ame,
//   candidatas_tiq/ame, alertas, dry_run, historico_actualizado,
//   ruta_detalle_json (solo si CONTROL1 lo escribio en esta corrida), modo.
// Las correcciones autorizadas (si las hubo) se aplican ANTES de este paso
// (ver construir_payload.js), via v3.control1_institucional.
// aplicar_correcciones_institucional_recuperable: cada GLOBAL toca solo su
// caja de origen y un reintento nunca vuelve a corregir un GLOBAL que ya
// quedo en su estado FINAL. Nunca existe un tercer GLOBAL combinado.
//
// RECUPERACION DE PUBLICACION PARCIAL (07D es secuencial: TIQ, luego AME):
// si TIQ se subio a Drive pero AME fallo, un reintento reenvia el MISMO
// body. El par local ya esta cerrado desde el intento anterior, asi que
// esta corrida puede devolver YA_PROCESADO_SIN_CAMBIOS (sin
// historico_actualizado=true EN ESTA corrida) en vez de un cierre fresco.
// `cierreCompletado` reconoce AMBOS casos como "el par TIQ/AME esta en su
// estado FINAL, es seguro (re)publicar": 07D sube en modo "actualizar"
// (sobrescritura), asi que reintentar un archivo que ya quedo correcto en
// Drive es un no-op inofensivo -- nunca hace falta comparar contenido.
// Cualquier otro estado (p.ej. GLOBAL_MODIFICADO_REQUIERE_REVISION: el par
// actual difiere del que ya quedo cerrado) NUNCA cuenta como completado:
// fail closed, no se publica nada, se exige revision humana. Ver
// tests_v3/n8n_control1_institucional_drive/logic_reference.js (copia de
// referencia probada con Node puro) para el detalle de los casos.
const modo = (($('WEBHOOK control1').first().json.body) || {}).modo || 'dev';
const vacio = { debe_publicar: false, hay_detalle: false, hay_historico: false, publicar_global_tiq: false, publicar_global_ame: false };
if (modo !== 'official') {
  return [{ json: vacio }];
}
const body = ($('WEBHOOK control1').first().json.body) || {};
const r = $json.data || {};
if (r.resultado === 'ERROR' || r.estado === 'ERROR_TECNICO') {
  return [{ json: vacio }];
}
const rc = $('RESOLVER control1 (periodo y carpetas)').first().json;

// Detalle/revision institucional del periodo: solo si CONTROL1 lo escribio en ESTA corrida
// (mismo nombre canonico del periodo pedido).
