  let origen = 'v3';
  if (!m) { m = RE_LEGACY.exec(nombre); origen = 'legacy'; }
  if (!m) continue;
  const dia = Number(m[1]);
  const mesN = Number(m[2]);
  const anioN = Number(m[3]);
  if (anioN !== r.anio || mesN !== r.mes) continue;
  const d = new Date(Date.UTC(anioN, mesN - 1, dia));
